-- Server script.
local profiles = game.CloudStore.open("profiles")

game.Players.PlayerRemoving:Connect(function(player: Instance)
    local profile = { gold = player.attr.Gold }
    profiles:put(player.UserId, profile, nil, function(version, err)
        if err then
            warn("could not save profile: " .. err)
        end
    end)
end)

-- Server script: give each player 10 gold when they join.
local profiles = game.CloudStore.open("profiles")

game.Players.PlayerAdded:Connect(function(player: Instance)
    profiles:update(player.UserId, function(data)
        local gold = if data then data.gold else 0
        return { gold = gold + 10 }
    end)
end)

