-- Plugin script (plugins/build/init.lua).
plugin:Operator({
    Id = "build.flatten",
    Label = "Flatten",
    Params = {
        { Name = "Parts", Type = "instances", Hidden = true, From = "Selection" },
    },
    Execute = function(ctx: PluginContext, params)
        local edit = ctx.Edit :: PluginEdit
        for _, part: Instance in params.Parts do
            local size = part.Size
            edit:Reshape(part, Vector3.new(size.X, 1, size.Z), part.Position)
        end
        return true
    end,
})

